<?php $catalogReport=$catalogReport??false;$periods=[7=>'Last 7 days',30=>'Last 30 days',90=>'Last 90 days']; ?>
<form method="get" class="dashboard-range" data-staff-period><label for="dashboard-days">Reporting period</label><select id="dashboard-days" name="days"><?php foreach($periods as $n=>$label): ?><option value="<?= $n ?>" <?= $analytics['days']===$n?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><button class="btn btn-secondary btn-sm" type="submit" data-period-submit>Update</button><span class="muted small"><?= e(date('j M',strtotime($analytics['since']))) ?> – <?= e(date('j M Y',strtotime($analytics['until']))) ?></span></form>
<?php if(!$catalogReport): ?>
<div class="staff-metric-strip dashboard-metrics"><div class="staff-metric"><span>Orders placed</span><strong><?= number_format((int)$analytics['orders']) ?></strong></div><div class="staff-metric"><span>To prepare</span><strong><?= number_format((int)$analytics['ready_to_prepare']) ?></strong><small>COD or verified card payment</small></div><div class="staff-metric"><span>Delivered</span><strong><?= number_format((int)$analytics['statuses']['delivered']) ?></strong></div><div class="staff-metric"><span>Verified card orders</span><strong>₱<?= e(number_format((float)$analytics['verified_card_value'],2)) ?></strong><small>Sandbox value · not settlement</small></div></div>
<div class="analytics-grid"><section class="panel analytics-chart"><div class="panel-head"><h2>Orders over time</h2><span class="muted small">Daily orders</span></div>
<?php $series=$analytics['series'];$rawPeak=max(1,...array_values($series));$step=max(1,(int)ceil($rawPeak/4));$peak=$step*4;$points=[];$i=0;$countDays=count($series);foreach($series as $count){$points[]=round(38+($i++*650/max(1,$countDays-1)),2).','.round(166-($count/$peak*140),2);} ?>
<svg class="orders-chart" viewBox="0 0 710 198" role="img" aria-label="Daily order counts. Exact values are in the table below."><?php for($tick=0;$tick<=4;$tick++):$y=166-$tick*35; ?><line class="staff-chart-grid" x1="38" y1="<?= $y ?>" x2="688" y2="<?= $y ?>"/><text x="26" y="<?= $y+4 ?>" text-anchor="end"><?= $tick*$step ?></text><?php endfor; ?><polyline class="staff-chart-line" points="<?= e(implode(' ',$points)) ?>"/><?php $keys=array_keys($series);foreach(array_unique([0,(int)floor(($countDays-1)/3),(int)floor(2*($countDays-1)/3),$countDays-1]) as $index):$x=38+$index*650/max(1,$countDays-1);?><text x="<?= round($x,2) ?>" y="190" text-anchor="<?= $index===0?'start':($index===$countDays-1?'end':'middle') ?>"><?= e(date('j M',strtotime($keys[$index]))) ?></text><?php endforeach; ?></svg>
<details class="analytics-data"><summary>View daily counts</summary><p class="muted small">All orders placed, including cancellations.</p><div class="table-wrap"><table><thead><tr><th>Date</th><th class="num">Orders placed</th></tr></thead><tbody><?php foreach($series as $day=>$count): ?><tr><td><?= e($day) ?></td><td class="num"><?= (int)$count ?></td></tr><?php endforeach; ?></tbody></table></div></details>
</section><section class="panel"><div class="panel-head"><h2>Fulfillment status</h2><a href="<?= e(url('/admin/orders')) ?>">Manage orders</a></div><div class="analytics-bars"><?php foreach($analytics['statuses'] as $status=>$count): ?><div data-order-status="<?= e($status) ?>"><span><?= e(ucfirst($status)) ?></span><strong><?= (int)$count ?></strong><meter min="0" max="<?= max(1,$analytics['orders']) ?>" value="<?= (int)$count ?>"><?= (int)$count ?></meter></div><?php endforeach; ?></div></section></div>
<?php endif; ?>
<div class="analytics-grid"><section class="panel"><div class="panel-head"><h2>Stock attention</h2><a href="<?= e(url('/catalog/inventory')) ?>">Inventory</a></div><?php if(!$analytics['attention']): ?><p class="analytics-empty">All active products have more than 5 units in stock.</p><?php else: ?><ul class="analytics-list"><?php foreach($analytics['attention'] as $product): ?><li><a href="<?= e(url('/catalog/inventory?stock='.(int)$product['id'].'#stock-form')) ?>"><?= e($product['name']) ?><small><?= e($product['sku']) ?></small></a><strong><?= staff_status((int)$product['stock_qty']===0?'Out of stock':'Low stock') ?> · <?= (int)$product['stock_qty'] ?> left</strong></li><?php endforeach; ?></ul><?php endif; ?></section>
<section class="panel"><h2>Most ordered · fulfilled</h2><?php if(!$analytics['top']): ?><p class="analytics-empty">No delivered orders in this period.</p><?php else: ?><ol class="analytics-list"><?php foreach($analytics['top'] as $product): ?><li><span><?= e($product['name']) ?></span><strong><?= (int)$product['units'] ?> units</strong></li><?php endforeach; ?></ol><?php endif; ?><details class="staff-help"><summary>Which orders count?</summary><p>Units in delivered orders placed in this period. Cancelled, unpaid card and simulated payments are excluded.</p></details></section></div>
<?php if($catalogReport): ?><section class="panel"><div class="panel-head"><h2>Catalog by category</h2><a href="<?= e(url('/catalog/categories')) ?>">Manage categories</a></div><div class="analytics-bars"><?php foreach($analytics['categories'] as $category): ?><div><span><?= e($category['name']) ?></span><strong><?= (int)$category['products'] ?></strong><meter min="0" max="<?= max(1,(int)$analytics['stock']['total']) ?>" value="<?= (int)$category['products'] ?>"><?= (int)$category['products'] ?></meter></div><?php endforeach; ?></div></section><?php endif; ?>